/**
 * THE FRESH CONSUMER — loading the plugin, all the way to a tool call.
 *
 * Every other gate in this suite starts from odu's own checkout. That is not
 * first contact. First contact is a client that has installed odu's Agent
 * Plugin (https://agent-plugins.org/): it has a copy of `agent-plugin/` as a
 * plugin root, reads `mcp.json` there, and spawns what it names — with the
 * plugin root as the working directory and `PLUGIN_ROOT` / `PLUGIN_DATA` in the
 * environment, as the spec requires.
 *
 * This gate does exactly that against the TRACKED contents of `agent-plugin/`,
 * so a file a client would never receive cannot make it pass.
 *
 * ## What the `nix` shim buys, and what it does not
 *
 * The server's command is `nix run --accept-flake-config github:juspay/odu --
 * mcp`, and there is deliberately no override knob — a consumer that must pin
 * odu pins the whole plugin. So executing it honestly would fetch and build
 * upstream master inside a test. Instead a `nix` shim goes first on PATH: it
 * ASSERTS the exact argv and then execs the locally built binary with the shim
 * removed from PATH again (odu itself shells out to `nix`, and a shim still
 * shadowing it would break every run the service starts).
 *
 * That proves the plugin invokes nix correctly. It does NOT prove `nix run
 * github:juspay/odu` resolves; a broken upstream flake would still ship.
 * Accepted deliberately: the alternative is a multi-minute network build inside
 * an e2e.
 */

import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StdioClientTransport } from "@modelcontextprotocol/sdk/client/stdio.js";
import { spawnSync } from "node:child_process";
import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, beforeAll, describe, expect, it } from "bun:test";
import {
  BIG,
  buildOduBinary,
  cleanup,
  hermeticEnv,
  repoRoot,
  scratchDir,
} from "./harness";
import {
  headOf,
  killDaemon,
  makeWebFixture,
  SHARED_TOOLS,
  suitePortFor,
  tcpListening,
} from "./webHarness";

/** A DAG whose second node fails — so the tool call this ends on has something
 *  real to diagnose. */
const FAILING = `[metadata("ci")]
default: alpha beta

alpha:
    echo "alpha ok"

beta: alpha
    echo "beta is about to fail"
    exit 3
`;

/** The plugin's `mcp.json`, as the spec shapes it. */
interface McpConfig {
  $schema: string;
  mcpServers: Record<
    string,
    { type: string; command: string; args?: string[]; cwd?: string }
  >;
}

let oduBin: string;
/** The installed plugin root — outside this repo, because a client's copy is. */
let pluginRoot: string;
/** The client-managed `PLUGIN_DATA` directory. */
let pluginData: string;
/** Where the `nix` shim lives, prepended to the server's PATH. */
let shimDir: string;
/** This gate's own state root and origin, so the daemon the server bootstraps
 *  is nobody else's. */
let stateDir: string;
let origin: string;
/** Read off the service the server started, so teardown reaps exactly it. */
let daemonHome: string | null = null;
let daemonPid: number | null = null;

/** The plugin's TRACKED files, copied out — what a client actually installs.
 *
 *  `git ls-files` rather than a recursive copy: it is the set a consumer
 *  receives, it honours `.gitignore`, and it takes the WORKING TREE's contents
 *  — so an uncommitted edit to the plugin under test is still what gets
 *  loaded. */
function installPlugin(): string {
  const dir = scratchDir("odu-e2e-plugin-");
  const copied = spawnSync(
    "sh",
    [
      "-c",
      `git ls-files -z -- agent-plugin | tar --null -T - -cf - | tar -xf - -C '${dir}' --strip-components=1`,
    ],
    { cwd: repoRoot, encoding: "utf-8", maxBuffer: BIG },
  );
  if (copied.status !== 0) {
    throw new Error(`e2e: could not export the plugin's tracked files: ${copied.stderr}`);
  }
  return dir;
}

/**
 * A `nix` that refuses to be anything but the MCP server's one call.
 *
 * An argv the server was not supposed to send is recorded and exits 97, so a
 * regression in that line fails as "here is what it actually ran" rather than
 * as a hang or a network fetch. `PATH` is restored before the exec because odu
 * shells out to the real `nix` for every run it starts.
 */
function writeNixShim(dir: string): void {
  const path = join(dir, "nix");
  writeFileSync(
    path,
    [
      "#!/usr/bin/env bash",
      "set -euo pipefail",
      'if [ "${1:-}" != "run" ] || [ "${2:-}" != "--accept-flake-config" ] \\',
      '   || [ "${3:-}" != "github:juspay/odu" ] || [ "${4:-}" != "--" ] \\',
      '   || [ "${5:-}" != "mcp" ]; then',
      `  printf '%s\\n' "$*" > ${JSON.stringify(join(dir, "nix.argv"))}`,
      "  exit 97",
      "fi",
      "shift 5",
      '# The shim is out of the way from here on: the service this becomes',
      '# starts coordinators that shell out to the REAL nix.',
      'export PATH="$ODU_E2E_REAL_PATH"',
      'exec "$ODU_E2E_BIN" mcp "$@"',
      "",
    ].join("\n"),
    { mode: 0o755 },
  );
}

beforeAll(() => {
  oduBin = buildOduBinary();
  pluginRoot = installPlugin();
  pluginData = scratchDir("odu-e2e-plugindata-");
  shimDir = scratchDir("odu-e2e-nixshim-");
  writeNixShim(shimDir);
  stateDir = scratchDir("odu-e2e-installstate-");
  mkdirSync(stateDir, { recursive: true });
  origin = `http://127.0.0.1:${suitePortFor("freshInstall")}`;
  // 900s: the nix build of odu in front of everything is minutes on a cold
  // store.
}, 900_000);

afterAll(() => {
  if (daemonPid !== null) killDaemon(daemonPid);
  for (const dir of [pluginRoot, pluginData, shimDir, stateDir, daemonHome]) {
    if (dir === undefined || dir === null) continue;
    try {
      rmSync(dir, { recursive: true, force: true });
    } catch (err) {
      process.stderr.write(`e2e: failed to remove ${dir}: ${String(err)}\n`);
    }
  }
});

/** `mcp.json` from the installed plugin root — where a client reads it. */
function mcpConfig(): McpConfig {
  return JSON.parse(readFileSync(join(pluginRoot, "mcp.json"), "utf-8")) as McpConfig;
}

describe("a client loading odu's Agent Plugin", () => {
  it("discovers exactly one skill, byte for byte the authored one", () => {
    expect(existsSync(join(pluginRoot, "plugin.json"))).toBe(true);
    const skills = join(pluginRoot, "skills");
    // EQUALITY. A second skill directory is a second vocabulary — that is what
    // the deleted `odu-mcp` was. "Contains odu" would not have seen it.
    expect(readdirSync(skills).sort()).toEqual(["odu"]);
    // A client that loaded something other than what this repo reviews would
    // be teaching agents an unreviewed skill.
    expect(readFileSync(join(skills, "odu", "SKILL.md"), "utf-8")).toBe(
      readFileSync(join(repoRoot, "agent-plugin/skills/odu/SKILL.md"), "utf-8"),
    );
  });

  it("finds one stdio MCP server with a single-token command", () => {
    const servers = mcpConfig().mcpServers;
    expect(Object.keys(servers)).toEqual(["odu"]);
    const odu = servers.odu;
    expect(odu?.type).toBe("stdio");
    // The spec requires `command` to be ONE executable token — a bare name or a
    // `./` plugin-relative path — never a shell string. A bare `nix` needs
    // nothing shipped in the package, so there is no launcher to lose.
    expect(odu?.command).toMatch(/^[^\s/]+$/);
  });

  it("bootstraps a service and answers a tool call through that exact server", async () => {
    const odu = mcpConfig().mcpServers.odu;
    if (odu === undefined) throw new Error("e2e: mcp.json declares no `odu` server");

    expect(
      await tcpListening(origin),
      "something is already serving this gate's origin",
    ).toBe(false);

    // Launched the way a conformant client launches it: `command` and `args`
    // from `mcp.json`, cwd at the plugin root (the spec's default when `cwd` is
    // omitted), and the two variables the spec has the client supply. Nothing
    // here reaches for `oduBin` — that path exists only inside the shim.
    const transport = new StdioClientTransport({
      command: odu.command,
      args: odu.args ?? [],
      cwd: pluginRoot,
      env: {
        ...hermeticEnv,
        PATH: `${shimDir}:${process.env.PATH ?? ""}`,
        PLUGIN_ROOT: pluginRoot,
        PLUGIN_DATA: pluginData,
        ODU_E2E_BIN: oduBin,
        ODU_E2E_REAL_PATH: process.env.PATH ?? "",
        ODU_STATE_DIR: stateDir,
        ODU_WEB_ORIGIN: origin,
      } as Record<string, string>,
    });
    const client = new Client({ name: "odu-e2e-install", version: "0.0.0" });
    const dir = makeWebFixture(FAILING);
    try {
      await client.connect(transport);

      // ONE VOCABULARY, reached through an installed plugin. Equality: a face
      // a consumer installs that could do one more thing than the browser can
      // is the second face growing back where nobody would look for it.
      const listed = await client.listTools();
      expect(listed.tools.map((t) => t.name).sort()).toEqual([...SHARED_TOOLS]);

      // COLD BOOTSTRAP THROUGH THE INSTALLED PATH. Nothing set a service up;
      // answering this at all is the server having started one.
      const read = await client.readResource({ uri: "surface://cells/service" });
      const first = read.contents[0];
      if (first === undefined || !("text" in first)) {
        throw new Error(
          `e2e: the service cell came back as ${JSON.stringify(first)} — expected a text resource`,
        );
      }
      const cell = JSON.parse(first.text) as {
        identity: { origin: string; pid: number; home: string };
        readiness: { state: string };
      };
      expect(cell.identity.origin).toBe(origin);
      // READY, not merely answering: a service still reconciling its catalog
      // would hand an agent a partial board with no way to tell.
      expect(cell.readiness.state).toBe("ready");
      daemonPid = cell.identity.pid;
      daemonHome = cell.identity.home;

      // AND A REAL TOOL CALL, to a real verdict. A listing proves a vocabulary;
      // only a run proves the installed face can do the thing it is for.
      const started = await client.callTool({
        name: "run_start",
        arguments: {
          checkout: dir,
          expectedSha: headOf(dir),
          requestId: "e2e-install-1",
          // The fixture has no GitHub origin, and strict mode is right to
          // refuse a run it could not report. `noPost` is strict WITHOUT the
          // GitHub writes, which is what a throwaway repo can honour.
          noPost: true,
        },
      });
      const receipt = JSON.parse(payload(started, "run_start")) as {
        runId: string;
        cursor: string;
        accepted: boolean;
      };
      expect(receipt.accepted).toBe(true);

      let cursor = receipt.cursor;
      let answer: {
        reason: string;
        settled: boolean;
        passed: boolean;
        cursor: string;
        failures: { logKey: string }[];
      };
      for (;;) {
        const waited = await client.callTool({
          name: "run_wait",
          arguments: { runId: receipt.runId, after: cursor, settle: true },
        });
        // RED CI IS NOT A TOOL ERROR — `payload` throws if it ever becomes one.
        answer = JSON.parse(payload(waited, "run_wait"));
        cursor = answer.cursor;
        if (answer.reason !== "still_running") break;
      }
      expect(answer.settled).toBe(true);
      expect(answer.passed).toBe(false);
      expect(answer.failures.length).toBeGreaterThan(0);

      // The evidence is ADDRESSED: echo the key, do not rebuild it.
      const page = JSON.parse(
        payload(
          await client.callTool({
            name: "log_read",
            arguments: { key: answer.failures[0]?.logKey, offset: -4096 },
          }),
          "log_read",
        ),
      ) as { text: string };
      expect(page.text.length).toBeGreaterThan(0);
    } finally {
      await client.close().catch(() => {});
      cleanup(dir);
      // The shim's own verdict on the server's argv, checked last so an argv
      // regression reports what was run rather than a connect that timed out.
      const offending = join(shimDir, "nix.argv");
      if (existsSync(offending)) {
        throw new Error(
          "e2e: the plugin's MCP server did not invoke nix the way the skill " +
            `promises — it ran: nix ${readFileSync(offending, "utf-8").trim()}`,
        );
      }
    }
  }, 900_000);
});

/** A tool call's text payload, or a failure that says what the tool actually
 *  answered. `isError` alone is "expected false, received true" on a CI runner
 *  nobody can attach to; the refusal underneath it carries the sentence. */
function payload(result: Record<string, unknown>, what: string): string {
  const text = String(
    (result.content as { text?: string }[] | undefined)?.[0]?.text ?? "",
  );
  if (result.isError === true) {
    throw new Error(`e2e: ${what} was refused — ${text}`);
  }
  return text;
}

/**
 * THE AUTHORITY WALL, ENFORCED — what a public client may not import.
 *
 * odu has one authority now: the shared service daemon. Every public command,
 * `odu surface`, and the `odu mcp` bridge are CLIENTS of it, and the value of
 * that arrangement is not that the code was moved — it is that a face cannot
 * quietly grow the authority back. Prose cannot promise that. This can.
 *
 * The failure mode this exists against is specific and it has happened before,
 * in this repository, in exactly this shape: a command that could not reach the
 * service "helpfully" fell back to doing the work itself. That fallback is
 * invisible in the common case and appears only when the shared service is
 * unreachable — which is precisely the moment two answers about one run start
 * to diverge, and the moment nobody is watching closely.
 *
 * ## The three authorities
 *
 * A module is a public client if a public command reaches it. Such a module may
 * not import:
 *
 *   - **execution** — `@odu/execution`'s coordinator: `runCommand`, the
 *     launcher, the retry policy. Starting or retrying a run is the service's,
 *     and a client that could spawn a coordinator is a second scheduler.
 *   - **the catalog's writes** — `@odu/run-history`'s store, import and
 *     retention. The catalog is the service's record of what happened; a second
 *     writer is a second history.
 *   - **the checkout dial** — `@odu/run-client/dial`. `.ci/odu.sock` is how the
 *     DAEMON reaches a coordinator, after proving which run is on the other end.
 *     A face that dialled it directly would be mutating a run it had not
 *     identified.
 *
 * ## Nothing is deliberately walled out any more
 *
 * This file used to name three exceptions. `odu dump` and `odu graph` "read a
 * justfile and touch no run"; `odu protect` "spends the CALLER's gh credential,
 * which the daemon has no way to borrow". Both defences were wrong.
 *
 * Reading a justfile is not the absence of authority, it is a SECOND RESOLVER:
 * what odu will run for a checkout is a question `run.start` answers through
 * the same engine, so a face answering it locally could disagree with the run
 * it was meant to predict, and nothing would notice. And the `protect` defence
 * described an odu that does not exist — the coordinator the daemon launches
 * has posted commit statuses with that same credential all along.
 *
 * Every public capability is a member on the shared surface now. The set this
 * walks is DERIVED from `src/main.ts`'s own imports, so a command cannot be
 * exempted by forgetting to list it.
 *
 * The walk is a PARSE rather than a line scan, and TYPE-ONLY EDGES COUNT: a
 * `import type { RunLauncher }` is how a port gets threaded back in one
 * refactor later, and the compiler would not object.
 */

import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "bun:test";
import ts from "typescript";

const packageRoot = join(import.meta.dirname, "..");
const srcRoot = join(packageRoot, "src");

/**
 * Every `@odu/cli/*` module `src/main.ts` imports — DERIVED, not listed.
 *
 * This used to be a literal array, on the reasoning that deriving the entry set
 * would "grow the allowlist automatically". That reasoning had it exactly
 * backwards, and the review that caught it was right: what a literal list grows
 * automatically is the set of modules the wall does not look at. A command
 * added to `main.ts` and forgotten here was simply not policed, and the suite
 * went on passing — which is how nine commands came to hold local authority
 * under a green test whose name says they do not.
 *
 * Deriving the ENTRY set makes the wall stricter. Deriving the FORBIDDEN set
 * would make it useless; that stays literal below, and the difference between
 * the two is the whole design.
 */
const mainImports = specifiersIn(
  readFileSync(join(packageRoot, "..", "..", "src", "main.ts"), "utf-8"),
  "main.ts",
);

/** `@odu/cli/foo` → `foo.ts`, which is how a specifier becomes a file in this
 *  package. Anything else `main.ts` imports is not ours to walk. */
const reachedFromMain = mainImports
  .filter((s) => s.startsWith("@odu/cli/"))
  .map((s) => `${s.slice("@odu/cli/".length)}.ts`)
  .sort();

/**
 * The two modules `main.ts` reaches that are NOT clients — with the reason each
 * is the thing a client talks to rather than a client.
 *
 * They are named here so that classifying a module is a decision somebody makes
 * on purpose, and the totality assertion below is what forces the decision:
 * a new `@odu/cli/*` import into `main.ts` belongs to one list or the other, and
 * belonging to neither is a failure rather than a silent exemption.
 */
const SERVICE_ROOTS: readonly string[] = [
  // The daemon itself: it binds the listener, builds the service and BINDS THE
  // PORTS. Reaching the engine is its entire job — `odu web` is how the
  // authority comes into existence, not a face onto it.
  "web.ts",
  // `run-coordinator` and `lease-hold`: argv entry points a launcher types,
  // never a person. `run-coordinator` IS the coordinator. See `./internalCli`
  // on why these moved out of `main.ts` — it was so that this derivation could
  // start at a root that is itself clean.
  "internalCli.ts",
];

/** What the wall polices: everything `main.ts` reaches that is not the service
 *  itself. */
const PUBLIC_CLIENTS = reachedFromMain.filter(
  (f) => !SERVICE_ROOTS.includes(f),
);

/** Import specifiers a public client may not reach, with the authority each
 *  one is. Prefix-matched, so a submodule cannot slip past the parent. */
const FORBIDDEN: readonly { prefix: string; authority: string }[] = [
  { prefix: "@odu/execution/coordinator", authority: "execution" },
  { prefix: "@odu/execution/just", authority: "pipeline ingest" },
  { prefix: "@odu/run-history/store", authority: "the catalog" },
  { prefix: "@odu/run-history/import", authority: "the catalog" },
  { prefix: "@odu/run-history/retention", authority: "the catalog" },
  { prefix: "@odu/run-history/query", authority: "the catalog" },
  { prefix: "@odu/run-client/dial", authority: "the checkout dial" },
  { prefix: "@odu/service/", authority: "the service's own internals" },
];

/**
 * The ONE exception, named with its reason.
 *
 * A daemon launcher has to know odu's own re-invocation argv and which
 * environment a child needs, and both live with the spawn machinery in
 * `@odu/execution/coordinator/spawn`. That module starts nothing by itself —
 * it is the pure description of HOW something would be started — and the thing
 * `webDaemonLaunch` starts is the service, not a run. Allowing the whole
 * `coordinator` prefix for this one file would allow the launcher and the retry
 * policy with it, so the exception is per-file AND per-specifier.
 */
const ALLOWED: Readonly<Record<string, readonly string[]>> = {
  "webDaemonLaunch.ts": ["@odu/execution/coordinator/spawn"],
};

/** Every module specifier a consumer's compiler would have to resolve: static
 *  imports and re-exports (`import type` included), `import x = require("…")`,
 *  dynamic `import()`, and `import("…").T` in type position. */
function specifiersIn(source: string, fileName: string): string[] {
  const parsed = ts.createSourceFile(
    fileName,
    source,
    ts.ScriptTarget.Latest,
    /* setParentNodes */ false,
    ts.ScriptKind.TS,
  );
  const out: string[] = [];
  const literal = (node: ts.Node | undefined): void => {
    if (node !== undefined && ts.isStringLiteralLike(node)) out.push(node.text);
  };
  const walk = (node: ts.Node): void => {
    if (ts.isImportDeclaration(node) || ts.isExportDeclaration(node)) {
      literal(node.moduleSpecifier);
    } else if (
      ts.isImportEqualsDeclaration(node) &&
      ts.isExternalModuleReference(node.moduleReference)
    ) {
      literal(node.moduleReference.expression);
    } else if (ts.isImportTypeNode(node)) {
      if (ts.isLiteralTypeNode(node.argument)) literal(node.argument.literal);
    } else if (
      ts.isCallExpression(node) &&
      node.expression.kind === ts.SyntaxKind.ImportKeyword
    ) {
      literal(node.arguments[0]);
    }
    ts.forEachChild(node, walk);
  };
  walk(parsed);
  return out;
}

/** Follow a public client's LOCAL imports too. A face that imported the engine
 *  through one hop of its own would satisfy a direct-edge check and hold the
 *  authority anyway, which is the whole trick this has to survive. */
function closureOf(entries: readonly string[]): Map<string, string[]> {
  const seen = new Map<string, string[]>();
  const queue = [...entries];
  while (queue.length > 0) {
    const file = queue.shift() as string;
    if (seen.has(file)) continue;
    const specifiers = specifiersIn(
      readFileSync(join(srcRoot, file), "utf-8"),
      file,
    );
    seen.set(file, specifiers);
    for (const spec of specifiers) {
      const local = localFile(spec);
      if (local !== null) queue.push(local);
    }
  }
  return seen;
}

/**
 * The file inside THIS package a specifier names, or `null` for anything else.
 *
 * Two spellings reach the same file and BOTH have to be followed.
 * `./leaseCmd` is the obvious one. `@odu/cli/leaseCmd` is the one that matters:
 * `packages/cli/package.json` declares `"exports": { "./*": "./src/*.ts" }` and
 * `node_modules/@odu/cli` is a symlink back to this package, so a module here
 * can import its own sibling by the package name — and that is the idiomatic
 * form in this tree, not an exotic dodge. `src/main.ts` uses it for every one
 * of its imports.
 *
 * Following only `.` left a one-hop hole big enough for everything the wall
 * exists to stop: an `import { … } from "@odu/cli/leaseCmd"` in a public client
 * was neither followed (not dot-prefixed) nor forbidden (`@odu/cli` is not an
 * authority), so that module and its whole import closure — the engine, the
 * lease machinery, `runCommand` — dropped silently out of the walk. It was
 * demonstrated against this tree: the wall stayed green.
 */
function localFile(specifier: string): string | null {
  if (specifier.startsWith("./")) return `${specifier.slice(2)}.ts`;
  if (specifier.startsWith("@odu/cli/")) {
    return `${specifier.slice("@odu/cli/".length)}.ts`;
  }
  return null;
}

describe("the authority wall", () => {
  const closure = closureOf(PUBLIC_CLIENTS);
  // THE ROOT IS POLICED TOO. `src/main.ts` seeds the derivation, so it was
  // never a member of the closure and its own imports were never checked —
  // and it is the single likeliest site for the regression this file exists
  // against, because every public verb's `case` body is in it. A `case "run":`
  // that called `runCommand(...)` when `connectOrStart` threw would have been
  // exactly the "fell back to doing the work itself" fallback the header
  // describes, and the wall would have stayed green. It is spelled under a
  // pseudo-name because it lives outside `srcRoot` and is not a module of this
  // package.
  const policed = new Map(closure).set("src/main.ts", mainImports);

  it("has public clients to police", () => {
    // A wall that policed nothing would pass forever. Both halves are asserted:
    // the entry points resolved, and the closure genuinely grew past them.
    expect(closure.size).toBeGreaterThanOrEqual(PUBLIC_CLIENTS.length);
    expect([...closure.keys()]).toContain("serviceCommands.ts");
    // And the derivation actually found the tree, rather than reading a
    // `main.ts` that had moved and quietly policing nothing.
    expect(reachedFromMain.length).toBeGreaterThan(5);
  });

  it("keeps the exempt set exactly these two, and no more", () => {
    // THE PRESSURE IS ON THE EXEMPTIONS, and it took a review to see that.
    //
    // This assertion used to compare `[...PUBLIC_CLIENTS, ...SERVICE_ROOTS]`
    // against `reachedFromMain` and call itself "the assertion that makes
    // forgetting impossible". `PUBLIC_CLIENTS` is DEFINED as
    // `reachedFromMain \ SERVICE_ROOTS`, so it was comparing (A \ S) ∪ (S ∩ A)
    // to A — equal for every possible input, and incapable of failing.
    //
    // A new import into `main.ts` was never the danger: it lands in
    // `PUBLIC_CLIENTS` by default and gets walled. The danger is the other
    // direction — adding a name to `SERVICE_ROOTS` silently removes that module
    // AND its whole transitive closure from the walk, which is the one edit
    // that can quietly un-police the engine. So the exempt set is pinned to a
    // literal here: growing it is a diff a reviewer sees and has to agree with.
    expect(
      [...SERVICE_ROOTS].sort(),
      "SERVICE_ROOTS changed. Every name here is a module the wall STOPS " +
        "walking, so adding one removes it and everything it imports from the " +
        "policed set. That is occasionally right — `web.ts` IS the service — " +
        "and it is never something to do in passing.",
    ).toEqual(["internalCli.ts", "web.ts"]);
  });

  it("names no service root that main.ts has stopped importing", () => {
    // A dead exemption is worse than none: it reads as a live decision and
    // policing has silently moved on without it.
    for (const root of SERVICE_ROOTS) {
      expect(
        reachedFromMain,
        `SERVICE_ROOTS names ${root}, which src/main.ts no longer imports — ` +
          "remove the exemption or restore the import.",
      ).toContain(root);
    }
  });

  it("walls every command the usage text advertises", () => {
    // The inventory, from the other side. `main.ts` is the only place a public
    // verb exists, so a verb whose dispatch does not reach a walled client is a
    // verb doing its own work — which is exactly the shape the review found
    // nine times over.
    for (const face of [
      "serviceCommands.ts",
      "serviceStatus.ts",
      "serviceVenue.ts",
      "servicePipeline.ts",
      "serviceCli.ts",
      "serviceMcp.ts",
    ]) {
      expect(
        PUBLIC_CLIENTS,
        `${face} is a public face and must be reachable from src/main.ts`,
      ).toContain(face);
    }
  });

  it("lets no public client reach execution, the catalog, or a checkout dial", () => {
    const offenders: string[] = [];
    for (const [file, specifiers] of policed) {
      for (const spec of specifiers) {
        const forbidden = FORBIDDEN.find((f) => spec.startsWith(f.prefix));
        if (forbidden === undefined) continue;
        if ((ALLOWED[file] ?? []).includes(spec)) continue;
        offenders.push(`${file} imports ${spec} (${forbidden.authority})`);
      }
    }
    expect(
      offenders,
      `${offenders.join("\n")}\n\nA public client has taken back authority ` +
        "that belongs to the shared service. Every public command is a client " +
        "of the daemon; it may render an answer and choose an exit code, and " +
        "it may not start a run, write the catalog, or dial a checkout's " +
        "socket. If a client genuinely needs something the service does not " +
        "expose, the fix is a member on the service surface — never a second " +
        "path to the engine, and never a fallback for when the daemon is " +
        "unreachable.",
    ).toEqual([]);
  });

  it("keeps the one allowance per-file AND per-specifier", () => {
    // The daemon launcher may name odu's own re-invocation argv. It may not
    // reach the run launcher standing beside it in the same directory.
    const launcher = closure.get("webDaemonLaunch.ts") ?? [];
    expect(launcher).toContain("@odu/execution/coordinator/spawn");
    expect(launcher).not.toContain("@odu/execution/coordinator/launcher");
    expect(launcher).not.toContain("@odu/execution/coordinator/recovery");
  });

  it("does not let the allowance travel to another file", () => {
    for (const [file, specifiers] of policed) {
      if (file === "webDaemonLaunch.ts") continue;
      expect(
        specifiers.filter((s) => s.startsWith("@odu/execution/coordinator")),
        `${file} reaches the coordinator. Only webDaemonLaunch.ts may, and ` +
          "only for the spawn description it needs to start the SERVICE.",
      ).toEqual([]);
    }
  });
});

/**
 * ONE PLUGIN, ONE SKILL, ONE MCP SERVER — asserted against this repo's tree.
 *
 * odu's agent face is an Agent Plugin (https://agent-plugins.org/, spec 1.0.0)
 * rooted at `agent-plugin/`: a `plugin.json`, the `odu` skill under `skills/`,
 * and the `odu` MCP server in `mcp.json`. odu's own `agent-distro.nix` profile
 * loads that very directory rather than a copy of it.
 *
 * ## What this file checks, and what it deliberately does not
 *
 * These are STATIC checks over the committed tree: the manifests are shaped the
 * way the spec requires, the profile loads them, and the skill teaches the one
 * vocabulary. They are cheap and run everywhere. They are not a loading gate —
 * `install.e2e.test.ts` loads the exported plugin the way a client does and
 * drives a real tool call through it.
 *
 * odu's agent face used to be two authored skills, `odu` and `odu-mcp`; while
 * two existed, an agent could read either and reach a different vocabulary.
 * Hence the insistence on exactly one of each below.
 */

import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "bun:test";
import { SHARED_TOOLS } from "./webHarness";

const repoRoot = join(import.meta.dirname, "..", "..");
const read = (rel: string): string => readFileSync(join(repoRoot, rel), "utf-8");
const readJson = <T>(rel: string): T => JSON.parse(read(rel)) as T;

const PLUGIN = "agent-plugin";
const SKILL = `${PLUGIN}/skills/odu/SKILL.md`;
const SPEC = "https://agent-plugins.org/schemas/1.0.0";

interface McpConfig {
  $schema?: string;
  mcpServers: Record<string, { type?: string; command?: string; args?: string[] }>;
}

/** The one command odu's MCP face is launched with, everywhere it is named:
 *  upstream master, unpinned, through Nix. `--accept-flake-config` because
 *  odu's flake declares a binary cache, and without it `nix run` stops on a
 *  trust prompt no MCP host can answer. */
const ODU_SERVER = {
  type: "stdio",
  command: "nix",
  args: ["run", "--accept-flake-config", "github:juspay/odu", "--", "mcp"],
};

describe("odu's Agent Plugin", () => {
  it("has a conformant plugin.json", () => {
    const manifest = readJson<Record<string, unknown>>(`${PLUGIN}/plugin.json`);
    expect(manifest.$schema).toBe(`${SPEC}/plugin.schema.json`);
    expect(manifest.name).toBe("odu");
    // The spec's manifest schema is CLOSED. An unknown field is reported and
    // ignored by a conformant client, which is a silent no-op for whoever
    // added it — so it is refused here instead.
    const allowed = [
      "$schema",
      "name",
      "version",
      "description",
      "author",
      "homepage",
      "repository",
      "license",
      "keywords",
      "extensions",
    ];
    for (const key of Object.keys(manifest)) {
      expect(allowed, `plugin.json has a non-spec field "${key}"`).toContain(key);
    }
  });

  it("declares exactly one MCP server, and it is the shared-service bridge", () => {
    const config = readJson<McpConfig>(`${PLUGIN}/mcp.json`);
    // The spec requires mcp.json to target the same version as plugin.json, or
    // a client disables MCP for the whole plugin.
    expect(config.$schema).toBe(`${SPEC}/mcp.schema.json`);
    expect(Object.keys(config).sort()).toEqual(["$schema", "mcpServers"]);
    expect(Object.keys(config.mcpServers)).toEqual(["odu"]);
    // `command` is a single bare token and the rest is `args`: the spec forbids
    // a shell string, and Nix is the only supported runtime — a server reaching
    // for bun or a source entry point would be a second way to run odu.
    expect(config.mcpServers.odu).toEqual(ODU_SERVER);
  });

  it("is what odu's own agent-distro profile loads, not a copy of it", () => {
    // Maintainers get the published plugin exactly as consumers do, plus the
    // maintainer-only `dev/` plugin — which is its own package, so nothing in it
    // can ride along into `agent-plugin/`.
    const profile = read("agent-distro.nix");
    expect(profile).toMatch(/plugins\s*=\s*\[\s*\.\/agent-plugin\s+\.\/dev\s*\]/);
    const dev = readJson<Record<string, unknown>>("dev/plugin.json");
    expect(dev.$schema).toBe(`${SPEC}/plugin.schema.json`);
    expect(dev.name).toBe("odu-dev");
  });

  it("publishes exactly one skill", () => {
    // EQUALITY. A second skill directory is a second vocabulary — that is what
    // the deleted `odu-mcp` was. "Contains odu" would not have seen it.
    expect(readdirSync(join(repoRoot, PLUGIN, "skills")).sort()).toEqual(["odu"]);
  });

  it("teaches one vocabulary in the skill it does publish", () => {
    const skill = read(SKILL);
    // THE WHOLE SHARED VOCABULARY, from the same list the MCP faces are
    // asserted against. A verb that reached the contract without reaching the
    // skill is a capability an agent has and cannot find, which is the same
    // failure as not having it — and the list grew from five to thirteen
    // precisely by people adding to one and not the other.
    for (const verb of SHARED_TOOLS) {
      expect(skill, `the skill never mentions ${verb}`).toContain(verb);
    }
    // Nothing deleted may still be TAUGHT — but the skill is allowed, and
    // expected, to NAME what is gone in its closing removal notice. An agent
    // arriving with stale knowledge of the nine tools is better served by being
    // told they no longer exist than by their silent absence, so the two are
    // different things and the check has to tell them apart. Everything before
    // "## What changed" is instruction; the notice below it is history.
    const marker = "## What changed";
    expect(skill, "the skill has no removal notice").toContain(marker);
    const teaches = skill.slice(0, skill.indexOf(marker));
    const notice = skill.slice(skill.indexOf(marker));
    for (const gone of [
      "wait_for_settle",
      "node_rerun",
      "node_cancel",
      "lane_cancel",
      ".ci/odu.sock",
      "bun run start",
      "odu mcp --service",
      "odu runs",
      "--linger",
    ]) {
      expect(teaches, `the skill still teaches "${gone}", which no longer exists`)
        .not.toContain(gone);
    }
    // And the notice must actually say the nine tools are gone, rather than
    // leaving an agent to discover it as a tool that is not there.
    for (const named of ["wait_for_settle", "node_rerun", "odu runs"]) {
      expect(notice, `the removal notice never mentions ${named}`).toContain(
        named,
      );
    }
  });

  it("teaches the MCP command the plugin actually ships", () => {
    // A skill documenting a different launch than `mcp.json` declares would be
    // telling a hand-configuring user to wire something no client runs.
    expect(read(SKILL)).toContain(
      "nix run --accept-flake-config github:juspay/odu -- mcp",
    );
  });
});

/**
 * End-to-end over `odu mcp` — the ONE agent face, and the only one.
 *
 * This file used to drive the per-checkout MCP server: nine tools of its own, a
 * dial of `.ci/odu.sock`, and run authority that no other face could see. That
 * server is deleted, and what replaced it is a BRIDGE — bare `odu mcp` dials the
 * singleton web service and projects the same verbs the browser and
 * `odu surface` project, under the same names.
 *
 * Four properties are worth an e2e rather than a unit test, and every one of
 * them is about the seam between processes rather than about a tool:
 *
 *   - **A cold host gets a working face.** An MCP host launches this bridge on a
 *     machine where nothing has ever run odu. That is the ORDINARY first
 *     contact, not an edge case, and it is the one the old face never had to
 *     handle because it carried its own authority. Here the bridge must start
 *     the service itself, verify it is ready, and answer — and it must do so
 *     through the REAL launcher an MCP config points at, not through a
 *     convenient in-process shortcut.
 *   - **Two cold faces converge on ONE daemon.** A person's terminal and an
 *     agent's bridge reaching an empty machine at the same instant is the
 *     ordinary morning, and two services would be two truths about one run.
 *   - **An occupied port is a REFUSAL, said quickly.** Not a timeout: an agent
 *     that is told `Request timed out` after a minute has learned nothing it
 *     can act on, and the thing it needed to hear was one sentence long.
 *   - **The vocabulary is exactly the shared one.** Not "contains the verbs" —
 *     EXACTLY them. An extra tool here would be the second face growing back,
 *     and it would grow back invisibly: nothing else in the suite would notice a
 *     face that could do one more thing than the browser can.
 *
 * Black-box like the rest of `tests/e2e`: no import from `src/`, the packaged
 * Nix binary only.
 */

import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StdioClientTransport } from "@modelcontextprotocol/sdk/client/stdio.js";
import { mkdirSync, mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, beforeAll, describe, expect, it } from "bun:test";
import {
  buildOduBinary,
  cleanup,
  hermeticEnv,
  scratchDir,
} from "./harness";
import {
  headOf,
  killDaemon,
  makeWebFixture,
  SHARED_TOOLS,
  startWebServiceViaCommand,
  suitePortFor,
  tcpListening,
  type WebWorld,
} from "./webHarness";

/** A DAG whose second node fails — the shape a diagnosis is about. */
const FAILING = `[metadata("ci")]
default: alpha beta

alpha:
    echo "alpha ok"

beta: alpha
    echo "beta is about to fail"
    exit 3
`;

let oduBin: string;

beforeAll(() => {
  oduBin = buildOduBinary();
}, 600_000);

/** Connect a real MCP client to `odu mcp`, in a world of its own. `env` decides
 *  which service the bridge reaches — and, when nothing is serving there, which
 *  one it starts. */
async function connectBridge(env: NodeJS.ProcessEnv): Promise<{
  client: Client;
  close: () => Promise<void>;
}> {
  const transport = new StdioClientTransport({
    command: oduBin,
    args: ["mcp"],
    env: env as Record<string, string>,
  });
  const client = new Client({ name: "odu-e2e", version: "0.0.0" });
  await client.connect(transport);
  return { client, close: () => client.close() };
}

/** A tool call's text payload, or a failure that says what the tool actually
 *  answered. `isError` alone is "expected false, received true" on a CI runner
 *  nobody can attach to; the refusal underneath it carries the sentence. */
function payload(result: Record<string, unknown>, what: string): string {
  const text = String(
    (result.content as { text?: string }[] | undefined)?.[0]?.text ?? "",
  );
  if (result.isError === true) {
    throw new Error(`e2e: ${what} was refused — ${text}`);
  }
  return text;
}

/** The service cell, decoded. A resource's content is a union of text and blob
 *  arms, so the text arm is NAMED rather than assumed: a blob here would be a
 *  transport change this suite should notice, not silently `String()` into
 *  "[object Object]" and fail three lines later on a missing field. */
async function readServiceCell(client: Client): Promise<ServiceCellish> {
  const read = await client.readResource({ uri: "surface://cells/service" });
  const first = read.contents[0];
  if (first === undefined || !("text" in first)) {
    throw new Error(
      `e2e: the service cell came back as ${JSON.stringify(first)} — expected a text resource`,
    );
  }
  return JSON.parse(first.text) as ServiceCellish;
}

/** As much of the service cell as this file reads. Mirrors — and is NOT
 *  imported from — `ServiceCellSchema`: black-box, so a shape imported from the
 *  code under test would agree with a mistake. */
interface ServiceCellish {
  identity: { origin: string; pid: number; home: string };
  readiness: { state: string };
}

/** The three facts a race compares, from either face. */
interface ServiceFacts {
  origin: string;
  pid: number;
  home: string;
  state: string;
}

function factsOf(cell: ServiceCellish): ServiceFacts {
  return {
    origin: cell.identity.origin,
    pid: cell.identity.pid,
    home: cell.identity.home,
    state: cell.readiness.state,
  };
}

describe("odu mcp — the shared-service bridge", () => {
  let world: WebWorld;

  beforeAll(async () => {
    world = await startWebServiceViaCommand(oduBin);
  }, 300_000);

  afterAll(() => world?.dispose());

  it("exposes EXACTLY the shared verbs — no face-local tool", async () => {
    const { client, close } = await connectBridge(world.env);
    try {
      const listed = await client.listTools();
      const names = listed.tools.map((t) => t.name).sort();
      // Equality, not containment. A face that could do one more thing than the
      // browser can is the second vocabulary growing back, and containment would
      // not see it. The list GREW — from five to thirteen — and equality is
      // exactly what made that growth a reviewed change rather than a drift:
      // every one of the eight new verbs had to be added here, in the shared
      // list, at the same time as it reached the contract.
      expect(names).toEqual([...SHARED_TOOLS]);
      // And none of the deleted per-checkout tools, named explicitly so a
      // reintroduction fails here with the name rather than as a count.
      for (const gone of [
        "run",
        "node_rerun",
        "wait_for_settle",
        "cancel",
        "runs",
        "node_cancel",
        "lane_cancel",
        "lease",
        "release",
      ]) {
        expect(names).not.toContain(gone);
      }
    } finally {
      await close();
    }
  }, 120_000);

  it("publishes the board and the service cell as resources, and not the DAG", async () => {
    const { client, close } = await connectBridge(world.env);
    try {
      const listed = await client.listResources();
      const uris = listed.resources.map((r) => r.uri);
      expect(uris).toContain("surface://cells/service");
      expect(uris).toContain("surface://collections/runs");
      // `nodes` is deliberately absent: it is a stream whose input is a run id,
      // and a stream that requires an input cannot be a static resource. An
      // agent reads a run's shape from `run_wait`'s answer instead.
      expect(uris.some((u) => u.includes("nodes"))).toBe(false);
    } finally {
      await close();
    }
  }, 120_000);

  it("names the same service the terminal face is talking to", async () => {
    // The whole claim of the consolidation, checked across two processes: the
    // bridge and `odu surface` must be looking at ONE daemon.
    const { client, close } = await connectBridge(world.env);
    try {
      const cell = await readServiceCell(client);
      expect(cell.identity.origin).toBe(world.origin);
    } finally {
      await close();
    }
  }, 120_000);

  it("drives a real run: start, wait, and a red node's addressed evidence", async () => {
    const dir = makeWebFixture(FAILING);
    try {
      const { client, close } = await connectBridge(world.env);
      try {
        const started = await client.callTool({
          name: "run_start",
          arguments: {
            checkout: dir,
            expectedSha: headOf(dir),
            requestId: "e2e-bridge-1",
            // The fixture has no GitHub origin, and strict mode is right to
            // refuse a run it could not report. `noPost` is strict WITHOUT the
            // GitHub writes, which is what a throwaway repo can honour.
            noPost: true,
          },
        });
        const receipt = JSON.parse(payload(started, "run_start")) as {
          runId: string;
          cursor: string;
          accepted: boolean;
        };
        expect(receipt.accepted).toBe(true);

        // The IDEMPOTENCY property, across the bridge: the same request id must
        // replay the receipt rather than start a second run. This is the one an
        // agent's lost tool call depends on.
        const again = await client.callTool({
          name: "run_start",
          arguments: {
            checkout: dir,
            expectedSha: headOf(dir),
            requestId: "e2e-bridge-1",
            // The fixture has no GitHub origin, and strict mode is right to
            // refuse a run it could not report. `noPost` is strict WITHOUT the
            // GitHub writes, which is what a throwaway repo can honour.
            noPost: true,
          },
        });
        const replayed = JSON.parse(payload(again, "the repeated run_start")) as {
          runId: string;
          replayed: boolean;
        };
        expect(replayed.runId).toBe(receipt.runId);
        expect(replayed.replayed).toBe(true);

        // Then wait to a verdict, carrying the cursor the way the skill teaches.
        let cursor = receipt.cursor;
        let answer: {
          reason: string;
          settled: boolean;
          passed: boolean;
          cursor: string;
          failures: { logKey: string }[];
        };
        for (;;) {
          const waited = await client.callTool({
            name: "run_wait",
            arguments: { runId: receipt.runId, after: cursor, settle: true },
          });
          // RED CI IS NOT A TOOL ERROR. The distinction an agent branches on,
          // asserted rather than assumed — `payload` throws if it ever becomes
          // one.
          answer = JSON.parse(payload(waited, "run_wait"));
          cursor = answer.cursor;
          if (answer.reason !== "still_running") break;
        }
        expect(answer.settled).toBe(true);
        expect(answer.passed).toBe(false);
        expect(answer.failures.length).toBeGreaterThan(0);

        // The evidence is ADDRESSED: echo the key, do not rebuild it.
        const key = answer.failures[0]?.logKey as string;
        const read = await client.callTool({
          name: "log_read",
          arguments: { key, offset: -4096 },
        });
        const page = JSON.parse(payload(read, "log_read")) as {
          text: string;
          complete: boolean;
        };
        expect(page.text.length).toBeGreaterThan(0);
      } finally {
        await close();
      }
    } finally {
      cleanup(dir);
    }
  }, 300_000);

  it("refuses a hand-built log key rather than guessing at it", async () => {
    const { client, close } = await connectBridge(world.env);
    try {
      const read = await client.callTool({
        name: "log_read",
        arguments: { key: "not/a/key/odu/issued" },
      });
      // A REFUSAL, which is a tool error — as distinct from red CI, which is
      // not. Both arms matter and this is the other one.
      expect(read.isError).toBe(true);
    } finally {
      await close();
    }
  }, 120_000);
});

/**
 * THE COLD-HOST GATE.
 *
 * A fresh machine, no daemon, and the bridge launched exactly the way an MCP
 * host launches it. Nothing in the suite sets a service up first — that is the
 * point. If the bridge could not bootstrap, an agent on a new machine would have
 * no way to get one: it has no terminal to run `odu web --background` in.
 *
 * A world of its own (its own origin, catalog and daemon home) so the daemon
 * this starts cannot be the one the suite above left running.
 */
describe("odu mcp — cold bootstrap", () => {
  it("starts the service itself when nothing is serving", async () => {
    const world = coldWorld("cold", suitePortFor("coldBootstrap"));
    let daemonHome: string | null = null;
    try {
      // THE PREMISE, ASSERTED — not reclaimed. This used to fix a hardcoded
      // 18493 and, finding something on it, try to stop that something through
      // `odu surface get service --origin`. Two things were wrong with that.
      // The port was shared: every other world in this suite derives its port
      // from the pid precisely so two checkouts do not fight, and this one did
      // not, so two suites on one machine each killed the other's daemon and
      // each re-bootstrapped — reported as "the stale cold-port daemon to go
      // away did not happen within 120000ms", in a test whose subject is that
      // nothing is serving. And the reclaim could START what it was emptying:
      // `ODU_WEB_ORIGIN` is in that env, so the probe's own bootstrap was
      // allowed and it spawned a daemon on the port under test. With a port of
      // this process's own there is nothing legitimate to reclaim, so this is a
      // precondition rather than a repair.
      expect(
        await tcpListening(world.origin),
        "something is already serving this suite's cold port",
      ).toBe(false);

      const { client, close } = await connectBridge(world.env);
      try {
        // One ordinary read. It can only be answered by a service, so answering
        // it at all is the bootstrap.
        const cell = await readServiceCell(client);
        expect(cell.identity.origin).toBe(world.origin);
        // READY, not merely answering: a service still reconciling its catalog
        // would give an agent a partial board with no way to tell.
        expect(cell.readiness.state).toBe("ready");
        world.adopt(cell.identity.pid);
        daemonHome = cell.identity.home;
      } finally {
        await close();
      }

      // And it OUTLIVES the bridge, which is the other half of the promise: the
      // host restarting its MCP server must not take the service with it.
      // Probed over TCP again — asking odu would start one and prove nothing.
      expect(
        await tcpListening(world.origin),
        "the service did not outlive the bridge that started it",
      ).toBe(true);
    } finally {
      world.dispose(daemonHome);
    }
  }, 300_000);

  it("two cold faces racing for one daemon converge on it", async () => {
    // The ordinary morning, not an edge case: a person opens a terminal and an
    // agent's host starts its MCP server, on a machine where nothing is
    // running. Two services would be two truths about one run, and the loser of
    // the race must not take the port from the winner — which is what
    // `serveWebService` claiming the pid gate BEFORE it binds is for.
    const world = coldWorld("race", suitePortFor("coldRace"));
    let daemonHome: string | null = null;
    try {
      expect(
        await tcpListening(world.origin),
        "something is already serving this suite's race port",
      ).toBe(false);

      // FOUR AT ONCE, and two of each face — a terminal client and an agent's
      // bridge bootstrap through the same seam but from different processes,
      // and a race that only ever ran one kind would not have exercised it.
      //
      // `Bun.spawn`, never `spawnSync`: a synchronous spawn blocks this thread
      // until the child exits, so a `Promise.all` over four of them would run
      // them one after another and assert nothing about a race at all.
      const viaTerminal = async (): Promise<ServiceFacts> => {
        const child = Bun.spawn([oduBin, "surface", "get", "service"], {
          env: world.env as Record<string, string>,
          stdout: "pipe",
          stderr: "pipe",
        });
        const [out, err, status] = await Promise.all([
          new Response(child.stdout).text(),
          new Response(child.stderr).text(),
          child.exited,
        ]);
        if (status !== 0) {
          throw new Error(
            `e2e: cold \`odu surface get service\` exited ${status}\n${err}`,
          );
        }
        return factsOf(JSON.parse(out));
      };
      const viaBridge = async (): Promise<ServiceFacts> => {
        const { client, close } = await connectBridge(world.env);
        try {
          return factsOf(await readServiceCell(client));
        } finally {
          await close();
        }
      };
      const answers = await Promise.all([
        viaTerminal(),
        viaBridge(),
        viaTerminal(),
        viaBridge(),
      ]);

      // ALL FOUR got a working service…
      for (const answer of answers) {
        expect(answer.state).toBe("ready");
        expect(answer.origin).toBe(world.origin);
      }
      // …and it is the SAME one. A second pid here would mean two daemons on
      // one address, which is either impossible (one of them never bound) or
      // catastrophic (one of them took the other's port), and both readings are
      // failures.
      const pids = new Set(answers.map((a) => a.pid));
      expect(
        [...pids],
        `four cold faces reached ${pids.size} different services`,
      ).toHaveLength(1);
      const winner = answers[0] as ServiceFacts;
      world.adopt(winner.pid);
      daemonHome = winner.home;

      // And the survivor is still the survivor a moment later — a loser that
      // had bound anything would have taken this address from it. Read from the
      // service itself rather than by scanning `ps`, because the daemon may be
      // a transient systemd unit rather than a process group and this suite
      // must not depend on which branch the host took.
      expect((await viaTerminal()).pid).toBe(winner.pid);
    } finally {
      world.dispose(daemonHome);
    }
  }, 300_000);
});

/**
 * THE OCCUPIED PORT, THROUGH THE AGENT'S EYES.
 *
 * A person who runs `odu web` on a taken port is told so in a sentence. An
 * agent used to be told nothing at all: the bridge's bootstrap polled the
 * readiness cell for its full sixty seconds, the MCP SDK's own request timeout
 * fired first, and the whole of what reached the agent was
 * `MCP error -32001: Request timed out` after sixty-three seconds. That is not
 * a refusal, it is an absence of one, and an agent cannot act on it.
 */
describe("odu mcp — a port that belongs to something else", () => {
  it("refuses in a sentence that names the port, fast", async () => {
    const port = suitePortFor("occupiedAgent");
    const world = coldWorld("occupied", port);
    // A plain TCP listener that accepts and says nothing — a foreign program,
    // as far as odu can tell, which is the whole point.
    const squatter = Bun.listen({
      hostname: "127.0.0.1",
      port,
      socket: { data: () => {}, open: () => {} },
    });
    try {
      const { client, close } = await connectBridge(world.env);
      try {
        const began = Date.now();
        let refusal: string | null = null;
        try {
          // A 30s ceiling deliberately BELOW the SDK's 60s default: if the fix
          // ever regresses, this fails as a timeout at 30s rather than
          // reproducing the original 63s one, and the assertion below still
          // says what was missing.
          await client.readResource(
            { uri: "surface://cells/service" },
            { timeout: 30_000 },
          );
        } catch (err) {
          refusal = String(err);
        }
        const elapsed = Date.now() - began;
        expect(refusal, "an occupied port answered as though it were fine").not
          .toBeNull();
        // THE SENTENCE, not merely a failure. A timeout is not a refusal.
        expect(
          refusal ?? "",
          "the refusal never names the port that is taken",
        ).toContain(String(port));
        expect(refusal ?? "").not.toContain("Request timed out");
        // FAST. The defect was sixty-three seconds of silence; the answer was
        // available in one. Fifteen seconds is slack for a loaded runner, and
        // still four times better than the SDK timeout that used to win.
        expect(
          elapsed,
          `the refusal took ${elapsed}ms — it is available immediately`,
        ).toBeLessThan(15_000);
      } finally {
        await close();
      }
    } finally {
      squatter.stop(true);
      world.dispose(null);
    }
  }, 300_000);
});

/**
 * A world with nothing in it: its own state root, its own origin, and a
 * teardown that reaps whatever it started.
 *
 * `adopt` rather than a return value because the pid is learned in the middle
 * of the test, and a daemon started by an attempt that then FAILED must still
 * be reaped — which is why the pid is recorded on the world the moment it is
 * known rather than at the end.
 */
function coldWorld(
  name: string,
  port: number,
): {
  origin: string;
  env: NodeJS.ProcessEnv;
  adopt: (pid: number) => void;
  dispose: (daemonHome: string | null) => void;
} {
  const root = scratchDir(`odu-e2e-${name}-`);
  const state = join(root, "state");
  mkdirSync(state, { recursive: true });
  const origin = `http://127.0.0.1:${port}`;
  let pid: number | null = null;
  return {
    origin,
    env: {
      ...hermeticEnv,
      ODU_STATE_DIR: state,
      ODU_WEB_ORIGIN: origin,
    } as NodeJS.ProcessEnv,
    adopt: (value) => {
      pid = value;
    },
    dispose: (daemonHome) => {
      if (pid !== null) killDaemon(pid);
      // The daemon home lives under the REAL `~/.local/state` — `daemonHome`'s
      // "state" placement ignores `XDG_STATE_HOME` on purpose, so moving the
      // origin is the only lever and the directory it leaves is this suite's to
      // remove. Twenty-one of them had accumulated on the author's machine
      // because nothing here removed any.
      for (const dir of [root, daemonHome]) {
        if (dir === null) continue;
        try {
          rmSync(dir, { recursive: true, force: true });
        } catch (err) {
          process.stderr.write(`e2e: failed to remove ${dir}: ${String(err)}\n`);
        }
      }
    },
  };
}

/**
 * The second door — `/mcp`'s gate, and the id bookkeeping behind it.
 *
 * `serveSurfaceApp` gates the websocket upgrade on `Origin` and nothing else,
 * because `@kolu/surface` was written when the upgrade was the only door.
 * Mounting an HTTP route beside it opened a second one, and a cross-site page
 * does not have to READ a reply to cause the mutation — so these tests are
 * about what must never get through, stated as a table of worlds rather than as
 * a claim in a comment.
 *
 * The other half is correlation. One `Server` behind one endpoint serves every
 * caller, they all start their JSON-RPC ids at 1, and a cancellation names one
 * of those ids. Getting that wrong does not fail loudly: it cancels somebody
 * else's run wait.
 */

import { describe, expect, it } from "bun:test";
import type { JSONRPCMessage } from "@modelcontextprotocol/sdk/types.js";
import { gateMcpRequest, RouteTransport } from "./serviceMcp";

const ORIGIN = "http://127.0.0.1:18440";

const headers = (over: Record<string, string | undefined> = {}) => ({
  "content-type": "application/json",
  host: "127.0.0.1:18440",
  ...over,
});

describe("what may POST to /mcp", () => {
  it("lets the browser this service serves talk to it", () => {
    expect(gateMcpRequest(headers({ origin: ORIGIN }), []).ok).toBe(true);
  });

  it("lets a non-browser client with no Origin talk to it", () => {
    // A CLI, an agent, `curl`. They are not the CSWSH vector, and refusing them
    // would break every non-browser consumer — which is why the content-type
    // check has to carry the weight instead.
    expect(gateMcpRequest(headers(), []).ok).toBe(true);
  });

  it("refuses a page from somewhere else — the mutation IS the attack", () => {
    // The reproduction from review: a POST carrying `run_cancel` with a hostile
    // Origin used to reach domain dispatch and answer 200.
    const verdict = gateMcpRequest(
      headers({ origin: "https://untrusted.example" }),
      [],
    );
    expect(verdict.ok).toBe(false);
    if (verdict.ok) return;
    expect(verdict.status).toBe(403);
  });

  it("answers to whatever name it was reached by", () => {
    // An SSH forward published on another machine's name, a tailnet name, a
    // proxy: the service does not keep a list of its own names, so a page
    // served from that name talks to it with no configuration.
    for (const host of [
      "pureintent.rooster-blues.ts.net:18440",
      "localhost:18440",
      "[::1]:18440",
    ]) {
      expect(
        gateMcpRequest(headers({ origin: `http://${host}`, host }), []).ok,
      ).toBe(true);
      expect(gateMcpRequest(headers({ host }), []).ok).toBe(true);
    }
  });

  it("refuses the content types a form can post without a preflight", () => {
    // `text/plain`, `multipart/form-data` and `application/x-www-form-urlencoded`
    // are the three a cross-origin form sends with no CORS preflight and no
    // Origin rules to lean on. Requiring JSON is what forces the preflight this
    // endpoint never answers.
    for (const type of [
      "text/plain",
      "multipart/form-data; boundary=x",
      "application/x-www-form-urlencoded",
      undefined,
    ]) {
      const verdict = gateMcpRequest(headers({ "content-type": type }), []);
      expect(verdict.ok).toBe(false);
      if (verdict.ok) continue;
      expect(verdict.status).toBe(415);
    }
  });

  it("accepts JSON with a charset, because that is what clients send", () => {
    expect(
      gateMcpRequest(
        headers({ "content-type": "application/json; charset=utf-8" }),
        [],
      ).ok,
    ).toBe(true);
  });

  it("lets an operator name an origin that differs from the Host", () => {
    // A reverse proxy that rewrites Host: the browser's origin is the public
    // name and the Host that arrives is loopback, so only the allowlist admits it.
    const allowed = ["https://box.tailnet.ts.net"];
    const proxied = headers({ origin: "https://box.tailnet.ts.net" });
    expect(gateMcpRequest(proxied, allowed).ok).toBe(true);
    expect(gateMcpRequest(proxied, []).ok).toBe(false);
  });
});

/** A transport wired to a server that answers whatever it is asked, on demand. */
function wired(): {
  transport: RouteTransport;
  seen: JSONRPCMessage[];
  answer: (mintedId: string, result: unknown) => void;
} {
  const transport = new RouteTransport();
  const seen: JSONRPCMessage[] = [];
  transport.onmessage = (message) => {
    seen.push(message);
  };
  return {
    transport,
    seen,
    answer: (mintedId, result) => {
      void transport.send({ jsonrpc: "2.0", id: mintedId, result } as JSONRPCMessage);
    },
  };
}

/** The id this transport minted for the nth request it received. */
function mintedIds(seen: JSONRPCMessage[]): string[] {
  return seen
    .map((m) => (m as { id?: unknown }).id)
    .filter((id): id is string => typeof id === "string");
}

describe("two callers, one endpoint", () => {
  it("gives each its own reply, wearing its own id", async () => {
    // Both clients start at id 1. Keyed on the caller's id, the second would be
    // told "already in flight" — or handed the first one's answer.
    const { transport, seen, answer } = wired();
    const a = transport.ask({ jsonrpc: "2.0", id: 1, method: "tools/list" }, {
      session: "A",
    });
    const b = transport.ask({ jsonrpc: "2.0", id: 1, method: "tools/list" }, {
      session: "B",
    });
    const [first, second] = mintedIds(seen);
    expect(first).not.toBe(second);
    answer(second as string, { who: "B" });
    answer(first as string, { who: "A" });
    expect(await a).toEqual({ jsonrpc: "2.0", id: 1, result: { who: "A" } });
    expect(await b).toEqual({ jsonrpc: "2.0", id: 1, result: { who: "B" } });
  });

  it("cancels only the session that asked", async () => {
    const { transport, seen, answer } = wired();
    const a = transport.ask({ jsonrpc: "2.0", id: 7, method: "tools/call" }, {
      session: "A",
    });
    const b = transport.ask({ jsonrpc: "2.0", id: 7, method: "tools/call" }, {
      session: "B",
    });
    const [mintedA, mintedB] = mintedIds(seen);

    await transport.ask(
      {
        jsonrpc: "2.0",
        method: "notifications/cancelled",
        params: { requestId: 7, reason: "user" },
      },
      { session: "A" },
    );
    // The server is told to cancel A's call, named by the id IT was given —
    // which is the whole point: `7` means nothing to the SDK, which saw
    // `odu-1`.
    const cancelled = seen.filter(
      (m) => (m as { method?: unknown }).method === "notifications/cancelled",
    );
    expect(cancelled).toHaveLength(1);
    expect(
      (cancelled[0] as unknown as { params: { requestId: string } }).params.requestId,
    ).toBe(mintedA as string);
    expect(await a).toBeNull();

    // B is untouched and still answerable.
    answer(mintedB as string, { who: "B" });
    expect(await b).toEqual({ jsonrpc: "2.0", id: 7, result: { who: "B" } });
  });

  it("DROPS a cancellation from a client that echoed no session", async () => {
    // Without a session there is no way to tell whose `7` this is. Applying it
    // to the most recent one would let any client cancel any other's call.
    const { transport, seen, answer } = wired();
    const a = transport.ask({ jsonrpc: "2.0", id: 7, method: "tools/call" }, {
      session: "A",
    });
    await transport.ask({
      jsonrpc: "2.0",
      method: "notifications/cancelled",
      params: { requestId: 7 },
    });
    expect(
      seen.filter((m) => (m as { method?: unknown }).method === "notifications/cancelled"),
    ).toHaveLength(0);

    const [minted] = mintedIds(seen);
    answer(minted as string, { still: "here" });
    expect(await a).toEqual({ jsonrpc: "2.0", id: 7, result: { still: "here" } });
  });

  it("releases a call whose HTTP request went away, and says so upstream", async () => {
    // The disconnect case. The POST is answered, the SDK is told the request is
    // cancelled — which is what interrupts the fiber, because every MCP request
    // runs under its own signal — and the RUN is untouched.
    const { transport, seen } = wired();
    const withdraw = new AbortController();
    const call = transport.ask({ jsonrpc: "2.0", id: 1, method: "tools/call" }, {
      session: "A",
      signal: withdraw.signal,
    });
    withdraw.abort();
    expect(await call).toBeNull();
    const cancelled = seen.filter(
      (m) => (m as { method?: unknown }).method === "notifications/cancelled",
    );
    expect(cancelled).toHaveLength(1);
    expect(
      (cancelled[0] as unknown as { params: { reason: string } }).params.reason,
    ).toContain("disconnected");
  });

  it("releases every waiter when the transport closes", async () => {
    const { transport } = wired();
    const call = transport.ask({ jsonrpc: "2.0", id: 1, method: "tools/list" }, {
      session: "A",
    });
    await transport.close();
    // A POST left hanging on a closed transport is a client that waits for
    // ever, which is worse than a null it can retry.
    expect(await call).toBeNull();
  });
});

